import{z as o,x as i,o as A,c as p,q as t,j as s,D as e,d as B,s as l,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"物理寄存器堆与释放","description":"","frontmatter":{"title":"物理寄存器堆与释放","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/prf-free-list.md","filePath":"cs/prf-free-list.md","lastUpdated":1791063341000}'),d={name:"cs/prf-free-list.md"};function m(D,E,F,f,C,R){const r=i("Mermaid");return A(),p("div",null,[E[2]||(E[2]=t('<h1 id="物理寄存器堆与释放" tabindex="-1">物理寄存器堆与释放 <a class="header-anchor" href="#物理寄存器堆与释放" aria-label="Permalink to &quot;物理寄存器堆与释放&quot;">​</a></h1><div class="epigraph"><p>物理寄存器堆的端口和项数卡住窗口；自由列表空了，前端即使预测对了也分配不出目的槽，只能停取。</p><footer>—— 据 Palacharla, Jouppi, and Smith, Complexity-Effective Superscalar Processors, ISCA 1997；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/register-renaming">上一课</a>规定每次写从自由列表取一个物理号。本课不重讲 RAT 查找。缺口是：<strong>物理寄存器何时回到自由列表、堆要多少读/写口、以及窗口被「槽耗尽」卡住与被 ROB 满卡住有何不同。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>物理寄存器不能在年轻指令写回时立刻释放：更年长的读者可能还没读，误预测还可能把 RAT 拨回这个槽。若等 ROB 提交才释放被覆盖的旧映射，则每个未提交写占一个槽，窗口上限 ≈ 物理数 − 架构寄存器数。槽不够时，即使发射队列空、功能单元闲，前端也要停。缺口不是再发明一种重命名，而是<strong>把生命周期钉在提交点上</strong>。</p><p><span class="marginnote">有的设计把结果先写 ROB 再在提交时搬进较小的架构堆（未来文件/ROB 数据），物理堆可以更小，但提交带宽变成搬移。当代宽核多半直接用大物理堆。</span></p><p><span class="marginnote">直觉类比：物理寄存器像图书馆的储物柜——每写一份新结果要租一个新柜子；旧柜子必须等「所有可能来看的人」都看过、且结果正式提交后才能回收。提前回收，晚到的读者翻到的是别人的东西。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自由列表：FIFO 或位图，每拍按译码宽度弹出目的寄存器。提交 \\(W\\) 条时，把各条 ROB 项里「被覆盖的旧物理号」推进自由列表。误预测：检查点里的自由列表头尾指针（或位图快照）一并恢复，已经分给冲刷路径的槽回到空闲。</p>',9)),(A(),s(n,null,{default:e(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FL%5B%22%E8%87%AA%E7%94%B1%E5%88%97%E8%A1%A8%22%5D%20--%3E%7C%22%E8%AF%91%E7%A0%81%E5%88%86%E9%85%8D%22%7C%20PRF%5B%22%E7%89%A9%E7%90%86%E5%AF%84%E5%AD%98%E5%99%A8%E5%A0%86%22%5D%0A%20%20PRF%20--%3E%7C%22%E5%86%99%E5%9B%9E%22%7C%20READY%5B%22%E5%B0%B1%E7%BB%AA%E4%BD%8D%E4%BE%9B%E5%94%A4%E9%86%92%22%5D%0A%20%20ROB%5B%22ROB%20%E6%8F%90%E4%BA%A4%22%5D%20--%3E%20REL%5B%22%E6%97%A7%E7%89%A9%E7%90%86%E5%8F%B7%E5%9B%9E%E8%87%AA%E7%94%B1%E5%88%97%E8%A1%A8%22%5D%0A%20%20FLUSH%5B%22%E5%86%B2%E5%88%B7%22%5D%20--%3E%20FL%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"PRF 读口：每拍发射宽度 × 每指令源数；写口：写回宽度。端口不够就复制 bank 或错开写回，这是面积与频率交易，见 Palacharla 对「复杂发射」的警告。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"三项结构同时限制 ILP：ROB 项、物理寄存器、发射队列槽。释放纪律保证：一个物理号在 RAT 或某条未提交指令的源字段里时，绝不会出现在自由列表。x0 / 立即数没有目的槽。",-1)),E[6]||(E[6]=a("p",null,"三种资源耗尽时，前端卡住的表现并不相同——诊断停顿先分辨卡在哪一项：",-1)),(A(),s(n,null,{default:e(()=>[l(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E7%AA%97%E5%8F%A3%E5%8D%A1%E5%9C%A8%E5%93%AA%E4%B8%80%E9%A1%B9%22%7D%20--%3E%20ROB%5B%22ROB%20%E6%BB%A1%EF%BC%9A%E6%8F%90%E4%BA%A4%E5%B8%A6%E5%AE%BD%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20ROB%20--%3E%20A%5B%22%E6%8C%87%E4%BB%A4%E7%95%99%E9%A9%BB%E7%AA%97%E5%8F%A3%E4%B8%8D%E5%89%8D%E7%A7%BB%3Cbr%2F%3E%E7%89%A9%E7%90%86%E6%A7%BD%E5%8F%AF%E8%83%BD%E8%BF%98%E5%85%85%E8%A3%95%22%5D%0A%20%20Q%20--%3E%20PRF%5B%22%E8%87%AA%E7%94%B1%E5%88%97%E8%A1%A8%E7%A9%BA%EF%BC%9A%E7%89%A9%E7%90%86%E6%A7%BD%E8%80%97%E5%B0%BD%22%5D%0A%20%20PRF%20--%3E%20B%5B%22%E8%AF%91%E7%A0%81%E7%A2%B0%E5%88%B0%E8%A6%81%E5%86%99%E7%9B%AE%E7%9A%84%E7%9A%84%E6%8C%87%E4%BB%A4%E5%B0%B1%E5%81%9C%3Cbr%2F%3EROB%20%E4%B8%8E%E9%98%9F%E5%88%97%E6%9C%AA%E5%BF%85%E6%BB%A1%22%5D%0A%20%20Q%20--%3E%20IQ%5B%22%E5%8F%91%E5%B0%84%E9%98%9F%E5%88%97%E6%BB%A1%EF%BC%9A%E4%BE%9D%E8%B5%96%E6%9C%AA%E8%A7%A3%E5%86%B3%22%5D%0A%20%20IQ%20--%3E%20C%5B%22%E5%B0%B1%E7%BB%AA%E6%8C%87%E4%BB%A4%E5%87%BA%E4%B8%8D%E5%8E%BB%20%E5%94%A4%E9%86%92%E9%93%BE%E5%8F%98%E6%85%A2%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">数字实例：物理堆 256 个、架构寄存器 32 个时，未提交的写最多占掉约 224 个自由槽——这就是「窗口上限 ≈ 物理数 − 架构数」的来历：每个架构寄存器的现行值总得占一个物理槽。</span></p><p>向量/FP 另有一套 PRF，端口与宽度不同；本课只要求整数堆与前端同宽分配。SIMD 扩展的重命名在 ISA 对照课已经有寄存器名，本课不重写向量 ISA。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把发射队列的唤醒矩阵画完，那是下一课。也不处理 store 数据的物理寄存器：store 的数据源同样是物理号，但释放仍跟在提交之后，且要等 LSQ 确认。物理堆的 ECC 与检查点面积是可靠性课的接口，这里只承认「快照很贵」。</p><p>后课默认：分配与释放以 ROB 提交为界；前端停顿的一个合法原因是自由列表空。就绪的物理号如何被选进 ALU，靠发射队列。</p><p><span class="marginnote">常见误区：初学者容易把所有停顿都归因「ROB 满」。自由列表空时，译码一碰到需要写目的寄存器的指令就停，此时 ROB 可能还空着一半——不看资源计数就找不到真正的瓶颈。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>物理寄存器在覆盖者提交后才释放；误预测恢复自由列表。</li><li>窗口可能被 PRF 而不是 ROB 先耗尽。</li><li>唤醒与选择逻辑是下一课发射队列。</li><li>出处：Palacharla, Jouppi, Smith, <em>ISCA</em>, 1997；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const c=o(d,[["render",m]]);export{u as __pageData,c as default};
